+  hashOpaqueToken,
+  lookupActiveBootstrap,
+  recordOperatorAudit,
+  resolveMigrationUrl,
+} from "@animal-helper/event-store";
+
+const email = "[REDACTED_EMAIL]";
+const origin = "https://animal-helper-admin.vercel.app";
+
+async function main() {
+  if (
+    process.env.VERCEL_ENV !== "production" ||
+    process.env.DATABASE_ENVIRONMENT !== "production" ||
+    process.env.DATABASE_SSL_MODE !== "verify" ||
+    process.env.ADMIN_ORIGIN !== origin
+  ) {
+    throw new Error("PRODUCTION_CONFIGURATION_MISMATCH");
+  }
+
+  const sql = postgres(resolveMigrationUrl(process.env), {
+    ...createSqlOptions(process.env, { max: 1 }),
+    prepare: false,
+    connect_timeout: 15,
+  });
+  try {
+    const [existing] = await sql<{
+      enabled: boolean;
+      has_passkey: boolean;
+    }[]>`
+      select o.enabled, exists (
+        select 1 from ah.operator_passkeys p
+        where p.operator_id = o.operator_id
+      ) as has_passkey
+      from ah.operators o where o.email = ${email}
+    `;
+    if (existing?.has_passkey) throw new Error("ALREADY_ENROLLED");
+    if (existing && !existing.enabled) throw new Error("ACCOUNT_DISABLED");
+
+    const token = await bootstrapOperator(sql, email);
+    const active = await lookupActiveBootstrap(sql, hashOpaqueToken(token), new Date());
+    if (!active?.enabled || active.email !== email) {
+      throw new Error("BOOTSTRAP_VERIFICATION_FAILED");
+    }
+    const [bootstrap] = await sql<{ expires_at: Date }[]>`
+      select expires_at from ah.operator_bootstraps
+      where token_hash = ${hashOpaqueToken(token)} and consumed_at is null
+    `;
+    if (!bootstrap) throw new Error("BOOTSTRAP_VERIFICATION_FAILED");
+
+    await recordOperatorAudit(sql, {
+      operatorEmail: "trusted_production_bootstrap",
+      action: "operator_bootstrap_created",
+      outcome: "accepted",
+    });
+    const envelope = publicEncrypt(
+      {
+        key: readFileSync("bootstrap-public-key.pem", "utf8"),
+        padding: constants.RSA_PKCS1_OAEP_PADDING,
+        oaepHash: "sha256",
+      },
+      Buffer.from(JSON.stringify({ token, email, origin, expiresAt: bootstrap.expires_at.toISOString() })),
+    ).toString("base64");
+    console.log("AH_BOOTSTRAP_ENVELOPE_V1:" + envelope);
+    console.log("AH_BOOTSTRAP_VERIFIED");
+  } finally {
+    await sql.end();
+  }
+}
+
+main().catch((error: unknown) => {
+  const safe = new Set([
+    "PRODUCTION_CONFIGURATION_MISMATCH",
