+    if (!entry.enabled || !entry.serviceKeys.includes(service) || !entry.verifiedOn ||
+      entry.verifiedOn > today || !entry.reviewDueOn || entry.reviewDueOn < today ||
+      !entry.sourceUrl || (!entry.phone && !entry.website)) return [];
+    if (entry.coverage.kind === "radius" && (!location || distanceKm(location, entry.coverage.center) > entry.coverage.radiusKm)) return [];
