+export const parseContactSpreadsheet = (buffer: ArrayBuffer, filename: string, encoding = "utf-8"): ImportWorkbook => {
+  if (!/\.(csv|xlsx?)$/iu.test(filename) || buffer.byteLength > MAX_IMPORT_BYTES) throw new Error("file");
+  const csv = /\.csv$/iu.test(filename);
+  const input = csv ? new TextDecoder(encoding, { fatal: true }).decode(buffer) : buffer;
+  const book = read(input, {
+    type: csv ? "string" : "array", raw: true, cellDates: true, cellHTML: false,
+    cellFormula: true, cellStyles: false, bookVBA: false, sheetRows: MAX_IMPORT_ROWS + 51,
+  });
+  if (!book.SheetNames.length || book.SheetNames.length > 20) throw new Error("file");
+  return { sheets: book.SheetNames.map((name) => {
+    const sheet = book.Sheets[name];
+    if (!sheet?.["!ref"]) return { name, rows: [], invalidRows: [], error: "empty" };
+    const range = utils.decode_range(sheet["!fullref"] as string ?? sheet["!ref"]);
+    if (range.e.r >= MAX_IMPORT_ROWS + 50 || range.e.c >= 50) return { name, rows: [], invalidRows: [], error: "limit" };
+    const rows: string[][] = [], invalidRows: number[] = [];
+    for (let row = 0; row <= range.e.r; row++) {
+      const values: string[] = [];
+      for (let col = 0; col <= range.e.c; col++) {
+        const cell = sheet[utils.encode_cell({ r: row, c: col })] as CellObject | undefined;
