import { fetchReportGuidance, saveReportGuidance, publishGuidance, type ReportGuidanceResponse, type AdminError } from "../api.js";
const props = defineProps<{ situation: string }>();
const contexts = computed((): { key: ReportGuidanceContext; label: string }[] => props.situation === "stray" ? [{ key: "stray", label: "Zatúlané zviera" }] : props.situation === "dead" ? [
  { key: "dead", label: "Bez uvedených podozrivých znakov" }, { key: "dead-suspicious", label: "Podozrivé znaky nálezu" },
] : [
  { key: "human", label: "Uviaznutie alebo ľudská činnosť" },
  ...(["near-road", "near-highway", "hit-road", "hit-highway", "railway", "other"] as const).map(key => ({ key: `road-${key}` as ReportGuidanceContext, label: t(`report.details.situation.${key}`) })),
]);
const context = ref<ReportGuidanceContext>("stray");
const kindKey = ref("");
const data = ref<ReportGuidanceResponse>();
const profile = ref<ReportGuidanceProfile>();
const saved = ref("");
const dirty = computed(() => JSON.stringify(profile.value) !== saved.value);
const pending = ref(false);
const error = ref("");
const notice = ref("");
const description = ref("");
const confirmed = ref(false);
const step = ref(0);
const items = computed(() => profile.value ? profileItems(profile.value) : []);
const selectedItem = computed(() => items.value[step.value]);
const animals = [...animalKinds].sort((a, b) => a.labelSk.localeCompare(b.labelSk, "sk"));
let generation = 0;
onScopeDispose(() => { generation++; });
function chooseProfile() {
  const found = data.value?.profiles.find(entry => entry.context === context.value && (entry.kindKey ?? "") === kindKey.value);
  profile.value = found ? structuredClone(found) : { context: context.value, ...(kindKey.value ? { kindKey: kindKey.value } : {}), warning: "", instructions: "", contacts: [] };
  saved.value = JSON.stringify(profile.value);
  confirmed.value = false;
  step.value = 0;
  notice.value = "";
}
function message(value: unknown) {
  const code = (value as AdminError).code;
  return t(code === "conflict" ? "backoffice.error.guidanceConflict" : code === "invalid_content" ? "backoffice.error.guidanceInvalid" : "backoffice.error.guidance");
}
async function load() {
  const request = ++generation;
  pending.value = true;
  error.value = "";
  try {
    const result = await fetchReportGuidance();
    if (request !== generation) return;
    data.value = result;
    chooseProfile();
  } catch (value) { if (request === generation) error.value = message(value); }
  finally { if (request === generation) pending.value = false; }
}
watch(() => props.situation, () => { context.value = contexts.value[0]!.key; kindKey.value = ""; void load(); }, { immediate: true });
watch([context, kindKey], chooseProfile);
function move(index: number, offset: number) {
  const contacts = profile.value?.contacts;
  if (!contacts || index + offset < 0 || index + offset >= contacts.length) return;
  const item = contacts.splice(index, 1)[0]!;
  contacts.splice(index + offset, 0, item);
}
async function save() {
  if (!data.value || !profile.value || pending.value) return;
  const request = generation;
  pending.value = true; error.value = ""; notice.value = "";
  try {
    const result = await saveReportGuidance({ expectedHash: data.value.contentHash, profile: JSON.parse(JSON.stringify(profile.value)) as ReportGuidanceProfile });
    if (request !== generation) return;
    data.value = result;
    chooseProfile();
    notice.value = "Koncept bol uložený. Zverejnite ho, aby sa zmeny zobrazili v aplikácii.";
