  const key = 'animal-helper.walk.pending'
  const storage = () => { try { return globalThis.sessionStorage } catch { return undefined } }
  return {
    stage(value) { try { storage()?.setItem(key, JSON.stringify(value)) } catch { /* IndexedDB remains available. */ } },
    async load() {
      const saved = await durable.load()
      let staged: WalkCheckpoint | undefined
      try { staged = JSON.parse(storage()?.getItem(key) ?? 'null') as WalkCheckpoint | undefined } catch { /* Ignore a corrupt journal. */ }
      if (staged?.streamId && (!saved || (staged.streamId === saved.streamId && (staged.savedAt ?? 0) >= (saved.savedAt ?? 0)))) return staged
      return saved
    },
    save: durable.save,
    async clear() { try { storage()?.removeItem(key) } catch { /* Clear durable storage below. */ } await durable.clear() }
