<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { t } from "@animal-helper/i18n";
import type { GuidancePreview } from "../guidance-preview.js";
const props = defineProps<{ walk: GuidancePreview }>();
const history = ref<string[]>([]);
watch(() => props.walk, (walk) => { history.value = [walk.start]; }, { immediate: true });
const current = computed(() => props.walk.screens.find((screen) => screen.id === history.value.at(-1)));
const visited = computed(() => new Set(history.value));
function go(target: string) { history.value.push(target); }
</script>
<template>
